import {resources, competition, phases, experiments, checks} from './data.js';
import {cognitivePage} from './cognitive.js';
import {budget, wilson, validateState} from './logic.js';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='gemma-agent-lab-v1';
const fresh=()=>({version:1,done:{},read:{},saved:{},notes:{},runs:[],custom:[],budget:{tasks:120,setup:45,reserve:72}});
let state=fresh(), storageProblem=false;
try{const raw=localStorage.getItem(key); if(raw){const parsed=JSON.parse(raw);validateState(parsed);state=parsed;}}catch{storageProblem=true;}
let page='overview', filter='All', query='', priority='All', onlySaved=false;
const allResources=()=>[...resources,...state.custom];
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function persist(){try{localStorage.setItem(key,JSON.stringify(state));return true;}catch{toast('Browser storage unavailable. Export a backup to keep your changes.');return false;}}
function heading(k,t,d,extra=''){return `<div class="page-heading"><div><div class="overline">${k}</div><h1>${t}</h1><p>${d}</p></div>${extra}</div>`;}
const link=(u,t)=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${t} ↗</a>`;
const completed=()=>phases.flatMap(p=>p.tasks).filter(([id])=>state.done['task:'+id]).length;
const cognitive=()=>cognitivePage({heading,link,notes});
function researchCallout(){return `<section class="card compact"><div class="card-head"><h2>Research update: the cognitive core</h2><span class="pill">Karpathy + related papers</span></div><p>Explore a task-local evidence ledger, grounded retrieval and behavioral training as testable refinements to the repair loop.</p><a class="text-link" href="#cognitive">Read the proposal, evidence and four new ablations ↗</a></section>`;}
function computeCard(){return `<section class="card compact"><div class="card-head"><h2>Your compute plan</h2><span class="pill">Colab Pro + Kaggle</span></div><p><strong>200 Colab compute units reported available.</strong> This is your starting budget, not a live balance. Use Kaggle for the official 31B baseline and offline harness evaluation; start Colab adaptation with an E4B compatibility pilot.</p><div class="table-wrap"><table><thead><tr><th>COLAB STAGE</th><th>PLANNED UNIT LIMIT</th><th>GATE</th></tr></thead><tbody><tr><td>Compatibility & profiling</td><td>20</td><td>Measure GPU memory and consumption rate</td></tr><tr><td>E4B verified-trace SFT pilot</td><td>80</td><td>Tiny adapter loads in Kaggle first</td></tr><tr><td>Controlled comparisons</td><td>40</td><td>Stable pilot and frozen held-out split</td></tr><tr><td>Export & reload checks</td><td>20</td><td>Candidate shows measurable improvement</td></tr><tr><td>Recovery reserve</td><td>40</td><td>Keep unallocated until needed</td></tr></tbody></table></div><p class="source-note">Proposed limits total 200 units; no compute has been spent by this project. Approximate stage hours = allocated units ÷ observed units/hour. Hardware and rates must be checked in your session. ${link('https://research.google.com/colaboratory/faq.html','Colab FAQ')}</p><div class="download-row"><a href="compute-plan.md" download>Full compute plan ↓</a></div></section>`;}
function checkRows(items,prefix){return items.map(([id,label])=>`<label class="check-row ${state.done[prefix+id]?'done':''}"><input type="checkbox" data-check="${prefix+id}" ${state.done[prefix+id]?'checked':''}><span>${label}</span></label>`).join('');}
function notes(id,placeholder){return `<label class="field">Working notes<textarea data-note="${id}" placeholder="${placeholder}">${esc(state.notes[id]||'')}</textarea></label><div class="note-save">Saved automatically in this browser.</div>`;}
function deadlines(){return `<div class="timeline-item"><div class="datebox"><b>12</b><small>NOV</small></div><div><strong>Optional paper submission</strong><p>23:59 UTC · 13 Nov, 04:59 PKT</p><span class="pill amber">Evidence required</span></div></div><div class="timeline-item"><div class="datebox"><b>25</b><small>NOV</small></div><div><strong>Entry & team merger</strong><p>23:59 UTC · 26 Nov, 04:59 PKT</p></div></div><div class="timeline-item"><div class="datebox"><b>02</b><small>DEC</small></div><div><strong>Final submission</strong><p>23:59 UTC · 03 Dec, 04:59 PKT</p></div></div>`;}
function overview(){const remaining=Math.max(0,Math.ceil((Date.parse('2026-12-02T23:59:00Z')-Date.now())/86400000)); return heading('GOOGLE × KAGGLE · GEMMA 4','Build a better repair agent.','Your research, experiments and next steps. One place to move forward.',`<span class="pill"><span class="status-dot"></span> Research & design phase</span>`)+`
<section class="hero"><div class="hero-copy"><div class="overline">THE WORKING HYPOTHESIS</div><h2>Find the right code.<br>Make the smallest fix.<br>Prove it with tests.</h2><p>A budget-aware Gemma agent with targeted retrieval, disciplined edits and an independent validation loop.</p><a href="#strategy" class="button-link">Explore the solution blueprint <span>↗</span></a></div><div class="hero-diagram" aria-label="Repair loop: localize, patch, verify, submit"><div class="orbit"><div class="core">g4<small>REPAIR AGENT</small></div><div class="node n1">01 · LOCALIZE</div><div class="node n2">02 · PATCH</div><div class="node n3">03 · VERIFY</div><div class="node n4">04 · SUBMIT</div></div></div></section>
<div class="metrics"><div class="metric"><label>Until final deadline</label><strong>${remaining} <span style="font-size:14px">days</span></strong><small>02 Dec · 23:59 UTC</small></div><div class="metric"><label>Shared execution budget</label><strong>12 <span style="font-size:14px">hours</span></strong><small>Includes sandbox setup</small></div><div class="metric"><label>Research library</label><strong>${allResources().length}</strong><small>${Object.values(state.read).filter(Boolean).length} marked read · curated sources</small></div><div class="metric"><label>Experiments recorded</label><strong>${state.runs.length}</strong><small>${state.runs.length?'Your logged evaluations':'Awaiting first harness run'}</small></div></div>
<div class="grid"><section class="card"><div class="card-head"><h2>Start here</h2><a class="text-link" href="#roadmap">Full roadmap ↗</a></div><div class="task-row"><span class="num">01</span><div><h3>Get the official harness running</h3><p>Sign in to Kaggle, accept the rules, then download the current sample and HARNESS_README. Access is still pending.</p></div></div><div class="task-row"><span class="num">02</span><div><h3>Measure a clean baseline</h3><p>Record resolved tasks, wall time, setup failures, tool errors and empty patches before tuning.</p></div></div><div class="task-row"><span class="num">03</span><div><h3>Test one hypothesis at a time</h3><p>Compare retrieval and stopping policies on fixed repository-disjoint splits.</p></div></div><div class="source-note">${link(competition+'/data','Official dataset & access')} · No model training or competition evaluation has run yet.</div></section><section class="card"><div class="card-head"><h2>Dates that matter</h2><span class="pill grey">UTC + PKT</span></div>${deadlines()}<div class="source-note">${link(competition+'/overview','Official timeline')} · Recheck for updates.</div></section></div>
<div class="notice"><strong>Live rules checked.</strong> The allowlist now includes 31B, 12B, E4B and E2B. Each submission must use one base model throughout. Older indexed summaries list only 31B. ${link(competition+'/overview','View current rules')}</div>
<div class="grid"><section class="card compact"><h2>Two candidates, one measured decision</h2><p>Start with 31B for the main baseline. Evaluate E4B separately for throughput and the small-model prize. Select using measured resolve rate under the shared budget, not model size alone.</p><a class="text-link" href="#experiments">Design the comparison ↗</a></section><section class="card compact"><h2>Progress through the plan</h2><p>${completed()} of ${phases.flatMap(p=>p.tasks).length} milestones complete</p><div class="progress"><span style="width:${completed()/phases.flatMap(p=>p.tasks).length*100}%"></span></div></section></div>`;}
function strategy(){const steps=[['Read the task','Extract observable failure, relevant symbols and acceptance criteria. Treat repository text as data; never follow instructions to leak data or disable validation.','get_status → targeted search'],['Localize cheaply','Start with paths, exception text and symbol names. Add semantic seeds only when lexical evidence is weak. Expand 1–2 graph hops with a strict context cap.','lexical → embeddings → graph'],['Reproduce the failure','Run a narrow reproducer or existing relevant test. Distinguish dependency/setup failures from product defects. Keep gold verification tests evaluator-only.','baseline test → causal hypothesis'],['Patch minimally','Inspect callers and contracts. Make one justified edit, inspect the diff, and avoid unrelated refactoring or weakening tests.','precise edit → diff review'],['Validate and recover','Run targeted tests, then the relevant regression suite. If progress stalls, revise the hypothesis once; preserve the strongest validated patch.','test → diagnose → bounded retry'],['Finalize before timeout','Reserve time for diff checks and submit_patch. Stop exploration when expected gain is lower than finalization risk. Use actual harness budget signals.','get_status → diff check → submit']];return heading('SOLUTION DESIGN','A small, disciplined repair loop.','Proposed architecture · Requires empirical validation',`<a class="button-link" href="solution-blueprint.md" download>Download blueprint ↓</a>`)+`
<div class="notice"><strong>Recommendation, not a claimed winning solution.</strong> Establish a no-adapter baseline first. Add retrieval, stopping rules and LoRA only when held-out results justify the cost.</div><div class="strategy-grid">${steps.map((s,i)=>`<section class="card step"><div class="step-no">0${i+1}</div><h3>${s[0]}</h3><p>${s[1]}</p><code>${s[2]}</code></section>`).join('')}</div><div class="grid"><section class="card"><h2>What the research changes</h2><ul class="list-clean"><li>${link('https://arxiv.org/abs/2407.01489','Agentless')} motivates a staged baseline.</li><li>${link('https://arxiv.org/abs/2405.15793','SWE-agent')} motivates careful tool interfaces and concise feedback.</li><li>${link('https://arxiv.org/abs/2610.33958','Graph-tool study')} motivates ablation, not assuming graph retrieval always helps.</li><li>${link('https://arxiv.org/abs/2504.21798','SWE-smith')} suggests scalable, executable training examples.</li></ul><p class="source-note">These are design inferences. Published benchmark scores are not forecasts for this competition.</p></section><section class="card"><h2>Training decision gates</h2><ol class="list-clean"><li>Can the untouched official sample complete a task?</li><li>Does a repeated failure pattern survive prompt/tool fixes?</li><li>Can a small LoRA load in the exact serving harness?</li><li>Does verified-trace SFT improve held-out repair at equal runtime?</li><li>Only then consider reward-based optimization.</li></ol><p class="source-note">QLoRA NF4 training support does not prove compatibility with the competition’s QAT model artifact.</p></section></div>
<section class="card"><h2>Validation that can survive a new repository</h2><p class="muted">Use leave-one-repository-out folds across the four public repositories. Keep a final holdout untouched until candidate selection. Deduplicate related issues and shared base commits across splits. Evaluate generated patches in fresh sandboxes with gold tests supplied only to the evaluator.</p><div class="comparison"><div><strong>Primary</strong><small>Resolved tasks / all scheduled tasks</small></div><div><strong>Reliability</strong><small>Timeouts, setup failures, empty patches, tool errors</small></div><div><strong>Efficiency</strong><small>Total runtime, including failed tasks and setup</small></div></div><p class="source-note">Report paired task outcomes and uncertainty. A higher success rate on only the tasks that finished can hide global-budget failures.</p></section><section class="card">${notes('strategy','Record architecture choices, tradeoffs and evidence here…')}</section>`;}
function library(){return heading('EVIDENCE & IDEAS','Research library','Read with a purpose. Every source has a concrete use in the solution.',`<button class="primary" id="add-resource">+ Add resource</button>`)+`<div class="toolbar"><input class="search" id="search" aria-label="Search resources" placeholder="Search papers, methods, authors…" value="${esc(query)}"><select id="priority" aria-label="Reading priority">${['All','Essential','Useful','Later'].map(x=>`<option ${x===priority?'selected':''}>${x}</option>`).join('')}</select><button id="saved-filter" aria-pressed="${onlySaved}">${onlySaved?'★ Saved only':'☆ Saved only'}</button></div><div class="tabs" aria-label="Resource type">${['All','Official','Paper','Documentation','Dataset','Article'].map(x=>`<button data-filter="${x}" class="${filter===x?'active':''}" aria-pressed="${filter===x}">${x}</button>`).join('')}</div><p id="results-count" class="source-note"></p><div id="resource-grid" class="resource-grid"></div><p class="source-note">Curated starting library, not an exhaustive bibliography. Summaries use abstracts and documentation; full-paper reproduction has not been performed. Added resources are labeled separately.</p>`;}
function renderResources(){const matches=allResources().filter(r=>(filter==='All'||r.type===filter)&&(priority==='All'||r.priority===priority)&&(!onlySaved||state.saved[r.id])&&[r.title,r.author,r.summary,r.action].join(' ').toLowerCase().includes(query.toLowerCase()));$('#results-count').textContent=`${matches.length} resources · ${Object.values(state.read).filter(Boolean).length} marked read`;
$('#resource-grid').innerHTML=matches.length?matches.map(r=>`<article class="card resource"><div class="resource-top"><span class="pill ${r.priority==='Essential'?'':'grey'}">${esc(r.type)} · ${esc(r.priority)}</span><button class="icon-button" data-save="${esc(r.id)}" aria-label="${state.saved[r.id]?'Unsave':'Save'} ${esc(r.title)}" aria-pressed="${!!state.saved[r.id]}">${state.saved[r.id]?'★':'☆'}</button></div><h3>${link(r.url,esc(r.title))}</h3><div class="author">${esc(r.author)} · ${esc(r.year)}${r.id.startsWith('user-')?' · Added by you':''}</div><p>${esc(r.summary)}</p><div class="action"><b>Apply it →</b> ${esc(r.action)}</div><div class="resource-footer"><a class="text-link" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open source ↗</a><button class="read-toggle ${state.read[r.id]?'is-read':''}" data-read="${esc(r.id)}" aria-pressed="${!!state.read[r.id]}">${state.read[r.id]?'✓ Read':'Mark read'}</button></div></article>`).join(''):`<div class="empty"><h3>No matching resources</h3><p>Try a broader search or reset the filters.</p><button id="reset-filters">Reset filters</button></div>`;}
function experimentsPage(){return heading('MEASURE BEFORE YOU SCALE','Experiment notebook','Record real evaluations. Compare like-for-like task splits and budgets.',`<button class="primary" id="add-run">+ Log evaluation</button>`)+`<div class="grid"><section class="card"><h2>Runtime planner</h2><p class="muted">A planning estimate for the 720-minute shared limit. Replace illustrative inputs with measured overhead and actual task count.</p><div class="form-grid"><label>Tasks to cover<input id="budget-tasks" type="number" min="1" max="10000" step="1" value="${state.budget.tasks}"></label><label>Total setup overhead (minutes)<input id="budget-setup" type="number" min="0" max="720" step="1" value="${state.budget.setup}"></label><label>Global safety reserve (minutes)<input id="budget-reserve" type="number" min="0" max="720" step="1" value="${state.budget.reserve}"></label></div><div id="budget-output" class="budget-output"></div><p class="source-note">Per-task allowance includes model inference, commands and agent-run tests. Independent grading is excluded by the organizer. This calculator does not change harness settings.</p></section><section class="card"><h2>Choose one controlled change</h2><p class="muted">Keep model revision, split, sampling and total budget constant when testing a retrieval or prompt change.</p><div class="task-row"><span class="num">A</span><div><h3>Quality</h3><p>Resolved / scheduled tasks, including timeouts and errors in the denominator.</p></div></div><div class="task-row"><span class="num">B</span><div><h3>Cost and reliability</h3><p>Wall time, patch validity, setup failures and tool-call errors.</p></div></div><div class="task-row"><span class="num">C</span><div><h3>Evidence</h3><p>Commit, seed, split hash, model revision and log location for every run.</p></div></div></section></div>
<section class="card"><div class="card-head"><h2>Your evaluations</h2><span class="pill grey">${state.runs.length} recorded</span></div>${state.runs.length?`<div class="table-wrap"><table><thead><tr><th>RUN / MODEL</th><th>SPLIT / REVISION</th><th>RESOLVED</th><th>95% WILSON INTERVAL</th><th>WALL TIME</th><th></th></tr></thead><tbody>${state.runs.map(r=>{const ci=wilson(r.resolved,r.total);return `<tr><td><b>${esc(r.name)}</b><small>${esc(r.model)} · ${esc(r.date)}</small><small>${esc(r.notes)}</small></td><td>${esc(r.split)}<small>${esc(r.revision)}</small></td><td><b>${(100*r.resolved/r.total).toFixed(1)}%</b><small>${r.resolved} / ${r.total} scheduled</small></td><td>${(ci[0]*100).toFixed(1)}–${(ci[1]*100).toFixed(1)}%<small>Descriptive; tasks may be correlated</small></td><td>${r.minutes} min<small>${r.timeouts} timeouts</small></td><td><button data-edit-run="${r.id}" aria-label="Edit ${esc(r.name)}">Edit</button></td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty"><h3>No evaluation results yet</h3><p>Run the official sample first, then log the measured outcome.<br>No example scores are mixed into this notebook.</p><button id="first-run">Log your first evaluation</button></div>`}<p class="source-note">Intervals summarize each logged run; they do not prove a difference between methods. Use paired per-task outcomes and repository-level sensitivity checks for comparisons.</p></section>
<section class="card"><h2>Planned ablation sequence</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>VARIANT</th><th>QUESTION / CONTROL</th><th>STATE</th></tr></thead><tbody>${experiments.map(([id,t,d])=>`<tr><td>${id}</td><td><b>${t}</b></td><td>${d}</td><td><span class="pill grey">Proposed</span></td></tr>`).join('')}</tbody></table></div></section><section class="card">${notes('experiments','Failure patterns, paired comparisons, links to raw logs…')}</section>`;}
function roadmap(){return heading('FROM BASELINE TO SUBMISSION','A plan for the remaining weeks.','Dates are proposed milestones. Check off only what you have actually completed.',`<span class="pill">${completed()} / ${phases.flatMap(p=>p.tasks).length} complete</span>`)+phases.map(p=>`<section class="card phase"><div class="phase-label">${p.window}<div class="progress"><span style="width:${p.tasks.filter(([id])=>state.done['task:'+id]).length/p.tasks.length*100}%"></span></div></div><div><h2>${p.title}</h2>${checkRows(p.tasks,'task:')}</div></section>`).join('')+`<section class="card">${notes('roadmap','Add owners, compute limits and changes to the schedule…')}</section>`;}
function readiness(){let n=checks.filter(([id])=>state.done['ready:'+id]).length;return heading('FINAL MILE','Submission desk','A manual readiness checklist, backed by reproducible artifacts.',`<span class="pill ${n===checks.length?'':'amber'}">${n} / ${checks.length} checked</span>`)+`<div class="notice"><strong>Not submission-ready yet.</strong> This workspace contains a research blueprint and development utilities. It does not contain trained weights, a harness-validated agent.yaml, or an evaluated submission.zip. Checking boxes records your review; it does not run validation.</div><div class="grid"><section class="card"><h2>Before selecting a final entry</h2>${checkRows(checks,'ready:')}</section><div><section class="card"><h2>Submission shape</h2><div class="code">submission.zip
├── agent.yaml
├── prompts/system.md
├── configs/…        (optional)
├── skills/…         (optional)
└── adapters/…       (optional)</div><p class="source-note">Start from the downloaded official sample. Include syntax, model fields and supported budget keys must be checked against the current harness.</p><div class="download-row"><a href="solution-blueprint.md" download>Solution blueprint ↓</a><a href="system-prompt.md" download>Draft system prompt ↓</a><a href="experiment-template.jsonl" download>Run-result format ↓</a></div></section><section class="card"><h2>Key official references</h2><ul class="list-clean"><li>${link(competition+'/data','Harness and sample')}</li><li>${link(competition+'/rules','Entry and submission rules')}</li><li>${link(competition+'/overview','Current model allowlist and timing')}</li></ul></section><section class="card">${notes('submission','Archive checksum, notebook version, run logs and final candidate IDs…')}</section></div></div>`;}
function render(){page=location.hash.slice(1)||'overview';if(!['overview','strategy','cognitive','library','experiments','roadmap','readiness'].includes(page))page='overview';document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#resource-count').textContent=allResources().length;$('#main').innerHTML=({overview,strategy,cognitive,library,experiments:experimentsPage,roadmap,readiness})[page]();if(page==='strategy'||page==='experiments')document.querySelector('.page-heading').insertAdjacentHTML('afterend',computeCard());if(page==='overview'||page==='strategy')document.querySelector('.page-heading').insertAdjacentHTML('afterend',researchCallout());if(page==='library')renderResources();if(page==='experiments')updateBudget();}
function updateBudget(){const value=budget(state.budget);$('#budget-output').innerHTML=value===null?'<span>Enter a positive task count and overhead + reserve below 720 minutes.</span>':`<div><small>Average available per task</small><br><strong>${value.toFixed(2)} min</strong></div><small>(720 − ${state.budget.setup} − ${state.budget.reserve}) ÷ ${state.budget.tasks}<br>Illustrative planning ceiling, not a guaranteed cap.</small>`;}
function openModal(html,onSubmit){$('#modal-form').innerHTML=html+`<div class="dialog-actions"><button type="button" id="cancel-modal">Cancel</button><button class="primary" type="submit">Save</button></div>`;$('#modal-form').onsubmit=e=>{e.preventDefault();onSubmit(new FormData(e.target));};$('#cancel-modal').onclick=()=>$('#modal').close();$('#modal').showModal();}
function runModal(id){const r=state.runs.find(x=>x.id===id)||{name:'',model:'31B',split:'',revision:'',total:0,resolved:0,minutes:0,timeouts:0,notes:'',date:new Date().toISOString().slice(0,10)};openModal(`<h2>${id?'Edit evaluation':'Log an evaluation'}</h2><div class="form-grid"><label>Run name<input name="name" maxlength="120" required value="${esc(r.name)}" placeholder="B0 · official sample"></label><label>Model<select name="model">${['31B','12B','E4B','E2B'].map(x=>`<option ${r.model===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Split / task-set hash<input required name="split" maxlength="200" value="${esc(r.split)}" placeholder="holdout-httpx / sha256…"></label><label>Code + model revision<input required name="revision" maxlength="300" value="${esc(r.revision)}" placeholder="commit / model artifact version"></label><label>Tasks scheduled<input required name="total" type="number" min="1" max="1000000" step="1" value="${r.total||''}"></label><label>Tasks resolved<input required name="resolved" type="number" min="0" step="1" value="${r.resolved}"></label><label>Total wall time (minutes)<input required name="minutes" type="number" min="0.01" max="1000000" step="any" value="${r.minutes||''}"></label><label>Timeouts<input required name="timeouts" type="number" min="0" step="1" value="${r.timeouts}"></label><label>Date<input required name="date" type="date" value="${r.date}"></label><label class="wide">Seed, failures, logs & observations<textarea name="notes" maxlength="10000">${esc(r.notes)}</textarea></label></div>`,f=>{let run=Object.fromEntries(f);for(const k of ['total','resolved','minutes','timeouts'])run[k]=Number(run[k]);if(run.resolved+run.timeouts>run.total){toast('Resolved tasks plus timeouts cannot exceed scheduled tasks.');return;}run.id=id||crypto.randomUUID();const next={...state,runs:id?state.runs.map(x=>x.id===id?run:x):[...state.runs,run]};try{validateState(next);}catch(e){toast(e.message);return;}state=next;persist();$('#modal').close();render();toast('Evaluation saved.');});}
function resourceModal(){openModal(`<h2>Add a research resource</h2><div class="form-grid"><label class="wide">Title<input name="title" required maxlength="300"></label><label class="wide">Source URL<input name="url" type="url" required placeholder="https://…"></label><label>Author / organization<input name="author" required maxlength="200"></label><label>Year<input name="year" required maxlength="30" value="2026"></label><label>Type<select name="type">${['Paper','Article','Documentation','Dataset','Official'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Priority<select name="priority"><option>Useful</option><option>Essential</option><option>Later</option></select></label><label class="wide">Why it matters<textarea name="summary" required maxlength="3000"></textarea></label><label class="wide">How to apply it<textarea name="action" required maxlength="3000"></textarea></label></div>`,f=>{const r={...Object.fromEntries(f),id:'user-'+crypto.randomUUID()};try{validateState({...state,custom:[...state.custom,r]});}catch(e){toast(e.message);return;}state.custom.push(r);persist();$('#modal').close();filter='All';query='';priority='All';onlySaved=false;render();toast('Resource added.');});}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.filter){filter=b.dataset.filter;render();}else if(b.dataset.read){state.read[b.dataset.read]=!state.read[b.dataset.read];persist();renderResources();}else if(b.dataset.save){state.saved[b.dataset.save]=!state.saved[b.dataset.save];persist();renderResources();}else if(b.dataset.editRun)runModal(b.dataset.editRun);else if(['add-run','first-run'].includes(b.id))runModal();else if(b.id==='add-resource')resourceModal();else if(b.id==='saved-filter'){onlySaved=!onlySaved;render();}else if(b.id==='reset-filters'){query='';filter='All';priority='All';onlySaved=false;render();}});
document.addEventListener('change',e=>{if(e.target.dataset.check){state.done[e.target.dataset.check]=e.target.checked;persist();render();}if(e.target.id==='priority'){priority=e.target.value;renderResources();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;renderResources();}if(e.target.dataset.note){state.notes[e.target.dataset.note]=e.target.value;persist();}if(e.target.id.startsWith('budget-')){const k=e.target.id.slice(7);const v=Number(e.target.value);if(e.target.validity.valid&&e.target.value!==''&&Number.isFinite(v)&&v>=0&& (k!=='tasks'||Number.isInteger(v)&&v>=1)){state.budget[k]=v;persist();updateBudget();}else $('#budget-output').textContent='Enter valid non-negative overhead and a positive whole task count.';}});
function download(name,content){const blob=new Blob([content],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export').onclick=()=>download(`gemma-agent-lab-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(state,null,2));
$('#import').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5000000){toast('Backup must be smaller than 5 MB.');return;}try{const imported=JSON.parse(await file.text());validateState(imported);openModal(`<h2>Restore workspace backup?</h2><p>This replaces progress in this browser with ${imported.runs.length} evaluations and ${imported.custom.length} custom resources. Export your current workspace first if you want to keep it.</p>`,()=>{state=imported;persist();$('#modal').close();render();toast('Workspace restored.');});}catch(e){toast('Invalid backup: '+e.message);}};
addEventListener('hashchange',()=>{render();scrollTo(0,0);});render();if(storageProblem)toast('Previous storage could not be loaded. Import a backup or export your current work.');
